/**
 * Extracts the covered stand of the owner's `football-court` FBX into the
 * optimised GLB the 3D match stage instances around the pitch (ADR 0018).
 *
 *   pnpm --filter @footebas/web stadium:convert
 *
 * The source model is a caged five-a-side court with one stand. Only the stand
 * (structure, seats, roof) is kept: the pitch, goals, floodlights and crowd of
 * the stage are generated by code at full 105 x 68 m size.
 *
 * Output frame (model units, ~0.4 m): x along the stand, centred; y up from
 * the ground; z from 0 at the front row towards -z at the back. Three meshes
 * named `structure`, `seats` and `roof`, geometry only (welded, no UVs).
 *
 * Runs in Node with Three's FBXLoader + GLTFExporter (no native tooling).
 * Output: `apps/web/public/assets/stadium/stand.glb`.
 */
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// FBXLoader/GLTFExporter touch a few browser globals even for geometry-only
// work; these shims are enough for a headless conversion.
globalThis.self = globalThis;
globalThis.window = globalThis;
globalThis.document = {
  createElementNS: () => ({
    addEventListener() {},
    removeEventListener() {},
    set src(_value) {},
    style: {},
  }),
};
globalThis.FileReader = class {
  readAsArrayBuffer(blob) {
    blob.arrayBuffer().then((result) => {
      this.result = result;
      this.onloadend?.();
    });
  }
};

const THREE = await import('three');
const { FBXLoader } = await import('three/examples/jsm/loaders/FBXLoader.js');
const { GLTFExporter } =
  await import('three/examples/jsm/exporters/GLTFExporter.js');
const { mergeVertices } =
  await import('three/examples/jsm/utils/BufferGeometryUtils.js');

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, '../../..');
const source = resolve(repoRoot, 'football-court/source/Football Court.fbx');
const output = resolve(here, '../public/assets/stadium');

/** Everything behind this z belongs to the stand (the court ends at -8). */
const STAND_FRONT_Z = -8.6;
const PART_OF = {
  'Black Tribune': 'structure',
  'Red Tribune': 'seats',
  proof: 'roof',
};

const fbx = readFileSync(source);
const group = new FBXLoader().parse(
  fbx.buffer.slice(fbx.byteOffset, fbx.byteOffset + fbx.byteLength),
  '',
);
group.updateMatrixWorld(true);

let mesh;
group.traverse((object) => {
  if (object.isMesh && !mesh) mesh = object;
});
if (!mesh) throw new Error('No mesh found in Football Court.fbx');

const geometry = mesh.geometry.clone();
geometry.applyMatrix4(mesh.matrixWorld);
const position = geometry.getAttribute('position');
const materials = Array.isArray(mesh.material)
  ? mesh.material
  : [mesh.material];
const parts = { structure: [], seats: [], roof: [] };
const point = new THREE.Vector3();

for (const range of geometry.groups) {
  const part = PART_OF[materials[range.materialIndex]?.name];
  if (!part) continue;
  let maxZ = -Infinity;
  const vertices = [];
  for (let index = range.start; index < range.start + range.count; index += 1) {
    const vertex = geometry.index ? geometry.index.getX(index) : index;
    point.fromBufferAttribute(position, vertex);
    maxZ = Math.max(maxZ, point.z);
    vertices.push(point.x, point.y, point.z);
  }
  if (maxZ > STAND_FRONT_Z + 0.2) continue;
  parts[part].push(...vertices);
}

const bounds = new THREE.Box3();
for (const vertices of Object.values(parts))
  for (let index = 0; index < vertices.length; index += 3)
    bounds.expandByPoint(
      point.set(vertices[index], vertices[index + 1], vertices[index + 2]),
    );
const centreX = (bounds.min.x + bounds.max.x) / 2;

const root = new THREE.Group();
root.name = 'stand';
let triangles = 0;
for (const [name, vertices] of Object.entries(parts)) {
  if (vertices.length === 0) throw new Error(`Stand part "${name}" is empty`);
  let part = new THREE.BufferGeometry();
  part.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));
  part.translate(-centreX, -bounds.min.y, -bounds.max.z);
  part = mergeVertices(part, 1e-3);
  part.computeVertexNormals();
  triangles += part.index.count / 3;
  const partMesh = new THREE.Mesh(
    part,
    new THREE.MeshStandardMaterial({ name, roughness: 1, metalness: 0 }),
  );
  partMesh.name = name;
  root.add(partMesh);
}

const glb = await new Promise((done, fail) => {
  new GLTFExporter().parse(root, (result) => done(Buffer.from(result)), fail, {
    binary: true,
  });
});

mkdirSync(output, { recursive: true });
writeFileSync(resolve(output, 'stand.glb'), glb);

const size = new THREE.Vector3();
bounds.getSize(size);
console.log(
  `stand.glb: ${glb.byteLength} bytes, ${triangles} triangles; ` +
    `${size.x.toFixed(2)} long x ${size.y.toFixed(2)} high x ${size.z.toFixed(2)} deep (model units)`,
);
